"""stages.implement.unified: generated by the graph.py split (P1)."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from ... import state as state_mod
from ... import prompts
from ...flow import ladder, outcome
from ...prompts import SYSTEM_PROMPT
from ...runtime.llm import DEFAULT_MAX_TOOL_ROUNDS
from ...runtime import coding_tools, conformance_delivery, effects, failures, commands as commands_mod, llm_step, observations, stage_services, tools as tools_mod
from ...runtime.implementation_tools import ImplementationToolset, Verification
from ...runtime.policy import PolicyError
from ...stages import feedback as feedback_mod
from ...stages.implement import header_transaction, intrinsics, repair_scope
from ...state import CfuDesignState

@coding_tools.delivery_failure_gate
@header_transaction.atomic_header
def implement_with_tools(state: CfuDesignState, *, client: Any = None) -> CfuDesignState:
    """Let the agent interleave HW/SW/DEV tools before the independent ladder."""
    toolbox = stage_services._toolbox_for_stage(state, "implementation")
    hardware_targets = frozenset(tools_mod.design_workspace_paths(state.get("run_root", "")).values())
    software_targets = frozenset(path for path, _ in stage_services._software_targets(state, toolbox))
    if not hardware_targets or not software_targets:
        raise ValueError("Stage 3 requires both hardware overlays and a software kernel target")
    if not state.get("apply_patch") or not state.get("run_commands") or state.get("dry_run"):
        raise ValueError(
            "Stage 3 autonomous coding requires patch application and command execution "
            "(disabled by --no-apply-patch, --no-run-commands or --dry-run)"
        )
    client = client or llm_step._llm(state)
    if not llm_step._tools_enabled(state, client):
        raise RuntimeError("the tool path needs an available tool-capable model")
    header_path = intrinsics._write_intrinsics_header(state, toolbox)
    if not header_path:
        raise ValueError("Stage 3 cannot generate the ISA intrinsics header")
    failure_info = observations.failure_index(state)
    feedback = feedback_mod.all_failure_feedback(state)

    need_hw, need_sw = repair_scope.required_domains(state, toolbox, failure_info)

    hardware_check_index = 0

    def check_elaboration() -> dict[str, Any]:
        nonlocal hardware_check_index
        problems = stage_services.hardware_integrity_problems(state, toolbox)
        if problems:
            return {"returncode": 1, "stderr_tail": "hardware integrity: " + "; ".join(problems)}
        hardware_check_index += 1
        commands = commands_mod.agent_cfu_check_commands(state, check_index=hardware_check_index)
        if not commands:
            return {"returncode": 1, "stderr_tail": "no isolated hardware check command"}
        check_toolbox = stage_services._toolbox_for_stage(state, "implementation")
        results = [effects.run_command(state, check_toolbox, argv,
                stage="implementation", rung="hw_check",
                              command_id="cfu_check_agent", timeout=1800, mutate=True)
                   for argv in commands]
        result = next((item for item in results if item.get("returncode") != 0), results[-1])
        rtl = (Path(state.get("workdir", ".")).resolve()
               / commands_mod._agent_cfu_check_out_dir(state, hardware_check_index) / "AgentCfu.v")
        return coding_tools.audit_hardware_result(state, check_toolbox, result, rtl)

    def check_compile() -> dict[str, Any]:
        check_toolbox = stage_services._toolbox_for_stage(state, "validation")
        problems = stage_services.benchmark_integrity_problems(check_toolbox)
        if problems:
            return {"returncode": 1, "stderr_tail": "benchmark integrity: " + "; ".join(problems)}
        commands = commands_mod._isolated_software_check_commands(state, check_toolbox)
        if not commands:
            return {"returncode": 1, "stderr_tail": "no isolated software check command"}
        results = [effects.run_command(state, check_toolbox, argv,
                stage="validation", rung="sw_check",
                              command_id=tools_mod.infer_command_id(argv, check_toolbox.policy),
                              timeout=1800, mutate=True) for argv in commands]
        return (next((item for item in results if item.get("returncode") != 0), results[-1]))

    def build_soc() -> dict[str, Any]:
        return coding_tools.build_soc_check(state, toolbox)

    def build_software() -> dict[str, Any]:
        """Compile the accelerated workload with the software build commands."""
        check_toolbox = stage_services._toolbox_for_stage(state, "validation")
        problems = stage_services.benchmark_integrity_problems(check_toolbox)
        if problems:
            return {"returncode": 1, "stderr_tail": "benchmark integrity: " + "; ".join(problems)}
        commands = commands_mod._software_build_commands(state, check_toolbox)
        if not commands:
            return {"returncode": 1, "stderr_tail": "no software build command"}
        results = [effects.run_command(state, check_toolbox, argv, stage="validation",
                                       rung="sw_build",
                                       command_id=tools_mod.infer_command_id(argv, check_toolbox.policy),
                                       timeout=1800, mutate=True) for argv in commands]
        return (next((item for item in results if item.get("returncode") != 0), results[-1]))

    conformance_on = bool(state.get("require_conformance", True))
    oracle_session = None
    if conformance_on:
        _prior_delivery, _delivery_problems = conformance_delivery.inspect_delivery(state, toolbox)
        oracle_session = conformance_delivery.ConformanceDelivery(
            state, toolbox, header_path, editable=True, diagnosis_required=bool(feedback))

    def check_conformance_syntax() -> dict[str, Any]:
        if oracle_session is None:
            return {"returncode": 1, "stderr_tail": "conformance is disabled (--no-conformance)"}
        _delivery, problems = oracle_session.current()
        if problems:
            return {"returncode": 1, "stderr_tail": "; ".join(problems)}
        argv = commands_mod._conformance_syntax_command(state, header_path)
        return effects.run_command(state, toolbox, argv, stage="implementation", rung="conformance_syntax",
                                   command_id="conformance_syntax", timeout=120, mutate=True)

    toolsets: list[ImplementationToolset] = []
    def factory(box, **kwargs):
        kwargs.pop("observation_index", None)
        toolset = ImplementationToolset(box, **kwargs)
        toolsets.append(toolset)
        return toolset

    def verdict(delivery: str) -> tuple[bool, str]:
        """The gate's decision, with the reason a rejection has to carry."""
        if not delivery.strip() or not toolsets:
            return False, "the delivery was empty"
        tools = toolsets[-1]
        if tools.repair_route and tools.repair_route["target"] in ("analysis", "contract"):
            return True, ""
        problems = stage_services.benchmark_integrity_problems(toolbox)
        if problems:
            return False, "benchmark integrity: " + "; ".join(problems)
        # Oracle staging may precede diagnosis; submitting a repair may not.
        if tools.diagnosis_required and not tools.hardware_session.diagnosis:
            return False, (
                "a repair round must file submit_repair_diagnosis before it can be submitted: "
                "state the observed failure, the root cause, the repair mapping and the "
                "regression risks, then submit again"
            )
        oracle_changed = bool(oracle_session is not None and oracle_session.changed)
        if state.get("repair_scope") == "conformance":
            need_change = bool(need_hw or need_sw or oracle_changed)
        else:
            need_change = True
        hw_changed = repair_scope.changed_paths(toolbox, tools.hardware_session).intersection(hardware_targets)
        sw_changed = repair_scope.changed_paths(toolbox, tools.software_session).intersection(software_targets)
        if need_change and not hw_changed and not sw_changed and not oracle_changed:
            return False, (
                "no hardware target was edited and no software target was edited, so "
                "nothing is applied: call edit_hardware/edit_software on the approved "
                "targets with the SEARCH/REPLACE edits, then submit a summary"
            )
        if need_hw and not hw_changed:
            return False, (
                "the current failures are hardware-side but no hardware target was edited: "
                f"call edit_hardware on {', '.join(sorted(hardware_targets))} with the "
                "SEARCH/REPLACE edits, then submit a summary"
            )
        if need_sw and not sw_changed:
            return False, (
                "the current failures are software-side but no software target was edited: "
                f"call edit_software on {', '.join(sorted(software_targets))}, "
                "then submit a summary"
            )
        if oracle_session is not None:
            _delivery, delivery_errors = oracle_session.current()
            if delivery_errors:
                return False, "conformance oracle is missing/stale/invalid: call write_conformance; " + "; ".join(delivery_errors)
        if any(not (toolbox.workdir / path).is_file() for path in (*hw_changed, *sw_changed)):
            return False, "an edited target is missing from the run workspace"
        problems = stage_services.hardware_integrity_problems(state, toolbox)
        if problems:
            return False, "hardware integrity: " + "; ".join(problems)
        try:
            exercises, why = intrinsics._software_exercises_cfu(
                state, toolbox, stage_services._software_targets(state, toolbox)
            )
        except (ValueError, PolicyError, OSError) as exc:
            return False, f"the CFU-usage check could not run: {exc}"
        if not exercises:
            return False, f"the accelerated path does not exercise the CFU: {why}"
        return True, ""

    def submit(delivery: str) -> tuple[bool, str]:
        # Model choice controls submission, not verdicts. Reopen local correction
        # budgets after rejection; the loop's turn/call caps remain authoritative.
        accepted, reason = verdict(delivery)
        if not accepted:
            for toolset in toolsets:
                toolset.grant_correction()
        return accepted, reason

    run_root = str(state.get("run_root", "") or "").rstrip("/")
    tool_names = ["read_file", "list_dir", "search_text", "list_command_logs", "inspect_failure"]
    if feedback:
        tool_names.extend(["submit_repair_diagnosis", "request_repair_route"])
    tool_names.extend([
        "edit_hardware", "edit_software", "check_hardware_elaboration",
        "check_software_compile", "build_soc", "build_software", "submit_stage",
    ])
    if conformance_on:
        tool_names.extend(["write_conformance", "check_conformance_syntax"])
    artifact_paths: list[tuple[str, str]] = []
    if run_root:
        evidence = [(f"{run_root}/07_analysis/workload_analysis.yaml", "workload analysis")]
        if state.get("isa_contract", True):
            evidence.append(
                (f"{run_root}/08_isa/cfu_isa.yaml", "frozen ISA contract (reuse exact hash-matched Run memory; read any missing encoding details)")
            )
        artifact_paths = stage_services.existing_evidence(state, evidence)
    conformance_step = (
        "3. Keep the conformance oracle honest with `write_conformance(oracle)`; "
        "the host renders C. Optionally check `check_conformance_syntax`; do not simulate "
        "in Implement. The oracle stays editable in every round: when a build or "
        "simulation failure shows the current checks are blind, strengthen them (add the "
        "case that would have caught it). Never weaken an oracle to make a failing design "
        "pass; a tautological or self-decided check is rejected.\n"
        if conformance_on else ""
    )
    submit_number = 4 if conformance_on else 3
    contract_free = not state.get("isa_contract", True)
    step_one = (
        "1. Read the scaffold/platform before writing, "
        "skipping only what the run memory already covers with matching hashes "
        "(re-read anything changed or needed for exact SEARCH text). "
        "There is NO ISA contract in this run: you design the instructions yourself. "
        "Write `cfu_intrinsics.h` from the intrinsic template below with `edit_software` "
        "(it is a normal software target): pick the encodings freely (custom0 opcode 0x0B, "
        "funct3 0..7, funct7 0..127) and keep the RTL encodings consistent with the header.\n"
        if contract_free else
        "1. Read the frozen ISA contract and the scaffold/platform before writing, "
        "skipping only what the run memory already covers with matching hashes "
        "(re-read anything changed or needed for exact SEARCH text).\n"
    )
    brief = prompts.stage_brief(
        "implementation (hardware + software)",
        design_guidance=prompts.cost_wall_guidance(state),
        deliverable=(
            "Apply the change to the workspace files with the editing tools, then call "
            "`submit_stage` with a short summary.\n"
            + step_one
            + "2. Write the design with `edit_hardware` and the accelerated kernel with "
            "`edit_software` (exact SEARCH/REPLACE edits). First delivery requires actual "
            "changes in both domains. A repair may reuse unchanged healthy sources "
            "only with a hash-checked prior implementation gate and real CFU software; "
            "do not add a comment-only software edit for a hardware-only repair. "
            "Before you submit, apply required changes; a delivery that pastes file "
            "content or a patch is not applied "
            "anywhere and will be rejected.\n"
            + conformance_step
            + f"{submit_number}. `submit_stage(delivery)`: `delivery` is a summary of what you changed, "
            "which evidence you ran, and what remains unknown — not the change itself. "
            "The gate rejects a submission that reports no applied change to a hardware "
            "and a software target on first delivery; repairs require applied changes "
            "to each failing domain and validated reuse of an unchanged healthy side."
        ),
        context=state.get("context", {}),
        workdir=str(Path(state.get("workdir", ".")).resolve()),
        run_root=run_root,
        tool_names=tool_names,
        tool_rounds=int(state.get("max_tool_rounds", DEFAULT_MAX_TOOL_ROUNDS) or DEFAULT_MAX_TOOL_ROUNDS),
        agent_tools=True,
        artifact_paths=artifact_paths,
        shared=prompts.workload_digest_block(
            state.get("workload_spec", {}), state.get("embench_profiles"),
        ),
    )
    schedule_line = (
        "\nYou schedule the work: read/search, edit_hardware, edit_software, "
        "check_hardware_elaboration, check_software_compile, build_soc, build_software, "
        + ("write_conformance and check_conformance_syntax " if conformance_on else "")
        + "may be used while budget remains. "
        + "Computational results must consume operand, vector or LSU payloads; never return fixed expected values. "
        + ("All simulation belongs to Verify, which consumes your committed oracle. "
           "Use independent reference and small bounded cases; never weaken the oracle to "
           "make a failing design pass, and strengthen it when the failure evidence shows "
           "the current checks could not see the defect."
           if conformance_on else
           "All simulation belongs to Verify; run no simulation in Implement.")
    )
    conformance_block = (
        ("\n\nConformance oracle authoring contract:\n"
         + prompts.conformance_prompt(state["task"], state.get("isa_spec") or {}, state.get("workload_spec") or {},
                                     agent_tools=True, workdir=str(toolbox.workdir), run_root=run_root,
                                     scalar_sources=[Path(p).name for p in
                                                     commands_mod.conformance_scalar_sources(state)])
         + "\nIn this tool session apply the oracle with write_conformance(oracle), not as your final response.")
        if conformance_on else ""
    )
    template_block = (
        ("\n\nIntrinsic template (starting point for `cfu_intrinsics.h`; adapt it freely):\n"
         "```c\n" + intrinsics.intrinsics_template_text(str(toolbox.workdir)) + "\n```")
        if contract_free else ""
    )
    # Differential mismatches are unattributed: either oracle or design may be wrong.
    scope_line = prompts.repair_scope_note(state)
    stage_user = (
        f"Task:\n{state['task']}\n\n"
        + brief
        + "\n\nHardware targets (edit with `edit_hardware`): "
        + ", ".join(sorted(hardware_targets))
        + "\nSoftware targets (edit with `edit_software`): "
        + ", ".join(sorted(software_targets))
        + schedule_line
        + "\n\n" + prompts.GENERALITY_REVIEW
        + "\nCurrent failure evidence:\n" + feedback
        + scope_line
        + (feedback_mod.repair_route_guidance(tool_mode=True) if feedback else "")
        + conformance_block
        + template_block
    )
    try:
        result, raw, calls = llm_step._run_agent_step(
            state, toolbox, stage="implement", label="stage3",
            artifact_stage="implementation",
            tool_calls_relpath="09_implementation/stage3_tool_calls.yaml",
            system=SYSTEM_PROMPT,
            user=stage_user,
            fallback="", client=client, native_tool_loop=True,
            submit_stage=submit, failure_observations=failure_info,
            toolset_factory=factory,
            toolset_kwargs={"hardware_targets": hardware_targets,
                            "software_targets": software_targets,
                            "check_elaboration": check_elaboration,
                            "check_compile": check_compile,
                            "verifications": (
                                Verification(
                                    name="build_soc",
                                    description=("Run the framework's SoC generation "
                                                 "(Scala compile + SpinalHDL elaboration + Verilog) "
                                                 "on the current overlay. Evidence only: the hw_build "
                                                 "rung reruns it and owns the gate."),
                                    label="SoC generation", final_gate="hw_build",
                                    budget=3, callback=lambda _args: build_soc()),
                                Verification(
                                    name="build_software",
                                    description=("Compile the accelerated workload with the framework's "
                                                 "software build command. Evidence only: the sw_build "
                                                 "rung reruns it and owns the gate."),
                                    label="software build", final_gate="sw_build",
                                    budget=3, callback=lambda _args: build_software()),
                            ),
                            "conformance_session": oracle_session,
                            "check_conformance_syntax": check_conformance_syntax,
                            "diagnosis_required": bool(feedback)},
        )
        tools = toolsets[-1]
        accepted, reason = verdict(result.text)
        if not accepted:
            raise failures.StageDeliveryFailure("accepted Stage 3 submission failed final audit: " + reason,
                                                stage="implement", tool_calls=calls)
        if tools.repair_route and tools.repair_route["target"] in ("analysis", "contract"):
            tools.rollback()
            update = ladder.repair_route_transition(state, tools.repair_route)
            update.update(llm_raw_outputs=[raw],
                          tool_calls=[llm_step._tool_call_summary(call) for call in calls])
            return update
        touched = repair_scope.changed_paths(toolbox, tools.hardware_session) | repair_scope.changed_paths(toolbox, tools.software_session)
        hardware_changed = sorted(touched.intersection(hardware_targets))
        software_changed = sorted(touched.intersection(software_targets))
        hw_hash = intrinsics._hardware_candidate_hash(state, toolbox)
        sw_hash = intrinsics._software_candidate_hash(toolbox, stage_services._software_targets(state, toolbox))
        stage_services._write_hardware_artifact(state, result.text, {"patch": "", "files": hardware_changed,
                                "applied": True, "proposed": True, "errors": []}, feedback)
        stage_services._write_software_artifact(state, result.text, {"patch": "", "files": software_changed,
                                "applied": True, "proposed": True, "errors": []}, [], feedback)
        delivery, _ = oracle_session.current() if oracle_session is not None else ({}, [])
        tools.commit()
    except Exception:
        if toolsets and not toolsets[-1].hardware_session.committed:
            toolsets[-1].rollback()
        raise
    return {
        "conformance_delivery": delivery, "repair_scope": "", "repair_route": {},
        "hardware_plan": result.text, "software_plan": result.text,
        "implementation_hw_summary": "Unified Stage 3 submission; formal gates pending",
        "implementation_sw_summary": "Unified Stage 3 submission; formal gates pending",
        "changed_design_files": hardware_changed, "changed_sw_files": software_changed,
        "llm_raw_outputs": [raw], "tool_calls": [llm_step._tool_call_summary(call) for call in calls],
        "stage_jobs": "validation",
        "gates": outcome.gates(state, {
            "implementation_route": {"ok": True, "next": "generate_soc"},
            "implementation_hw": {"ok": True, "applied": True, "files": hardware_changed,
                                  "candidate_hash": hw_hash, "reused": not bool(hardware_changed)},
            "implementation_sw": {"ok": True, "applied": True, "files": software_changed,
                                  "candidate_hash": sw_hash, "isa_hash": intrinsics._isa_digest(state),
                                  "intrinsics_header": header_path, "reused": not bool(software_changed)},
        }),
        "iteration_history": state_mod.append_history(state, "Stage 3 agent submitted HW/SW for independent validation."),
    }

implement_stage3 = implement_with_tools  # historical node alias
